import sys
from os import path
if path.exists('input.txt'):
	sys.stdin = open('input.txt', 'r')
	sys.stdout = open('output.txt', 'w')
for _ in range(int(input())):
	(n, m) = map(int, input().split())
	a = list(map(int, input().split()))
	ar = a[::-1]
	b = list(map(int, input().split()))
	larr = [0]
	rarr = []
	nrstl = 0 if a[0] == 1 else -1
	nrstr = -1
	for i in range(1, n):
		if a[i] > 0:
			larr.append(0)
			if a[i] == 1:
				nrstl = i
		else:
			larr.append(i - nrstl if nrstl != -1 else -1)
	for i in range(n - 1):
		if ar[i] > 0:
			rarr.append(0)
			if ar[i] == 2:
				nrstr = i
		else:
			rarr.append(i - nrstr if nrstr != -1 else -1)
	rarr.append(0)
	rarr = rarr[::-1]
	for i in range(m):
		st = b[i] - 1
		if larr[st] > -1 and rarr[st] > -1:
			print(min(rarr[st], larr[st]), end=' ')
		elif larr[st] != rarr[st]:
			print(max(larr[st], rarr[st]), end=' ')
		else:
			print(-1, end=' ')
	print()
